{

"kind": "propose",
"summary": "OOM kills in revision 2 due to memory limit being reached. Increase memory limit to prevent OOM.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_regression",
    "summary": "Current revision's memory limit (512Mi) was reached, causing OOM kills.",
    "supporting": ["ev-pod_states", "ev-container_memory"],
    "contradicting": [],
    "missing": ["pod_states.memory_usage_before_kill"],
    "status": "supported"
  },
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "Memory limit was exactly reached (512Mi), requiring a 25% increase to 640Mi.",
    "supporting": ["ev-container_memory", "ev-pod_states"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "catalog",
    "uid": "uid-deployment-catalog"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "640Mi"
        }
      }
    }
  },
  "expected_effect": "Prevents OOM kills by increasing memory limit beyond peak usage.",
  "rationale": "The container's memory limit (512Mi) was exactly reached, causing OOM kills. Increasing it by 25% to 640Mi provides buffer without requiring code changes. This matches the oom-limit-too-low profile criteria: memory_at_limit_before_kill=true, oom_without_recent_rollout=true, and no node memory pressure (evicted_for_node_memory=false).",
  "cited_evidence_ids": ["ev-container_memory", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "oom_without_recent_rollout"]
}
}
